import * as React from "react";
import Card, { type ArchiveProjectCardData } from "./card";
import archiveImages from "../images/portfolio_archive";
import type { PortfolioProject } from "../utils/livePortfolio";

const archiveImageMap = {
  "714": { logo: archiveImages.logo_714, thumb: archiveImages.thumb_714, large: archiveImages.big714 },
  afroboutik: { logo: archiveImages.logo_afroboutik, thumb: archiveImages.thumb_afroboutik, large: archiveImages.afroboutik },
  arthurquentin: {
    logo: archiveImages.logo_arthurquentin,
    thumb: archiveImages.thumb_arthurquentin,
    large: archiveImages.arthurquentin,
  },
  autoprocessor: {
    logo: archiveImages.logo_autoprocessor,
    thumb: archiveImages.thumb_autoprocessor,
    large: archiveImages.autoprocessor,
  },
  averna: { logo: archiveImages.logo_averna, thumb: archiveImages.thumb_averna, large: archiveImages.averna },
  bogotadespierta: {
    logo: archiveImages.logo_bogotadespierta,
    thumb: archiveImages.thumb_bogotadespierta,
    large: archiveImages.bogotadespierta,
  },
  cea: { logo: archiveImages.logo_cea, thumb: archiveImages.thumb_cea, large: archiveImages.cea },
  ccmm_lapress: {
    logo: archiveImages.logo_ccmm,
    thumb: archiveImages.thumb_ccmm_lapress,
    large: archiveImages.ccmm_lapress,
  },
  getmade: { logo: archiveImages.logo_getmade, thumb: archiveImages.thumb_getmade, large: archiveImages.getmade },
  inspection_residentielle: {
    logo: archiveImages.logo_inspection_residentielle,
    thumb: archiveImages.thumb_inspection_residentielle,
    large: archiveImages.inspection_residentielle,
  },
  mkds: { logo: archiveImages.logo_mkds, thumb: archiveImages.thumb_mkds, large: archiveImages.mkds },
  nellie: { logo: archiveImages.logo_nellie, thumb: archiveImages.thumb_nellie, large: archiveImages.nellie },
  solareh: { logo: archiveImages.logo_solareh, thumb: archiveImages.thumb_solareh, large: archiveImages.solareh },
  vk: { logo: archiveImages.logo_vk, thumb: archiveImages.thumb_vk, large: archiveImages.vk },
  wizard: { logo: archiveImages.logo_wizard, thumb: archiveImages.thumb_wizard, large: archiveImages.wizard },
} as const;

export type ArchivePortfolioProject = PortfolioProject & {
  imageKey: keyof typeof archiveImageMap;
};

export type ArchivePortfolioGridProps = {
  projects: ArchivePortfolioProject[];
  openLabel: string;
  closeLabel: string;
};

export default function ArchivePortfolioGrid({
  projects,
  openLabel,
  closeLabel,
}: ArchivePortfolioGridProps) {
  const archiveProjectsWithImages = projects
    .map((project) => {
      const images = archiveImageMap[project.imageKey];

      if (!images) {
        return null;
      }

      return {
        ...project,
        images,
      } as ArchiveProjectCardData;
    })
    .filter((project): project is ArchiveProjectCardData => Boolean(project));

  return (
    <div className="mt-6 grid gap-4 lg:grid-cols-5">
      {archiveProjectsWithImages.map((project) => (
        <Card
          key={project.title}
          project={project}
          openLabel={openLabel}
          closeLabel={closeLabel}
        />
      ))}
    </div>
  );
}
