import * as React from "react";
import { useAccessibleDialog } from "../utils/dialog";

type ImageAsset = {
  src: string;
  alt?: string;
  desc?: string;
};

export type ArchiveProjectCardData = {
  title: string;
  role: string;
  stack: string;
  year?: string;
  highlights: string[];
  note?: string;
  images: {
    logo: ImageAsset;
    thumb: ImageAsset;
    large: ImageAsset;
  };
};

type CardProps = {
  project: ArchiveProjectCardData;
  openLabel: string;
  closeLabel: string;
};

const Card: React.FC<CardProps> = ({ project, openLabel, closeLabel }) => {
  const [isOpen, setIsOpen] = React.useState(false);
  const dialogId = React.useId();
  const dialogRef = React.useRef<HTMLDivElement | null>(null);
  const closeButtonRef = React.useRef<HTMLButtonElement | null>(null);
  const triggerRef = React.useRef<HTMLButtonElement | null>(null);

  useAccessibleDialog({
    isOpen,
    onClose: () => setIsOpen(false),
    dialogRef,
    initialFocusRef: closeButtonRef,
    returnFocusRef: triggerRef,
  });

  const label = project.images.large.alt || project.title;

  return (
    <>
      <button
        type="button"
        onClick={(event) => {
          triggerRef.current = event.currentTarget;
          setIsOpen(true);
        }}
        className="group block w-full text-left focus:outline-none focus-visible:ring-2 focus-visible:ring-accent/40 rounded-2xl"
        aria-label={`${openLabel}: ${project.title}`}
      >
        <div className="flex h-full flex-col overflow-hidden rounded-2xl border border-neutral/20 bg-secondary shadow-sm transition-transform duration-300 group-hover:-translate-y-0.5">
          <div className="relative">
            <img
              src={project.images.thumb.src}
              alt={project.images.thumb.alt || `${project.title} thumbnail`}
              className="h-44 w-full object-cover grayscale"
              loading="lazy"
              decoding="async"
              width={1200}
              height={800}
            />
            <div className="absolute inset-0 bg-gradient-to-t from-primary/90 via-primary/30 to-transparent" />
            <img
              src={project.images.logo.src}
              alt={project.images.logo.alt || `${project.title} logo`}
              className="absolute bottom-3 left-3 h-24 w-auto rounded bg-primary/70 px-2 py-1"
              loading="lazy"
              decoding="async"
              width={240}
              height={120}
            />
          </div>
          <div className="flex flex-1 flex-col p-5">
            <h3 className="text-lg font-semibold leading-snug text-accent">{project.title}</h3>
            <p className="mt-1 text-sm text-neutral hidden lg:block">
              <span className="font-medium text-accent">{project.role}</span>
              {" · "}
              <span>{project.stack}</span>
              {project.year ? <span>{" · "}{project.year}</span> : null}
            </p>
            <ul className="mt-4 flex-1 space-y-2 text-sm text-accent hidden lg:block">
              {project.highlights.map((highlight) => (
                <li key={highlight} className="flex gap-2">
                  <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
                  <span className="min-w-0">{highlight}</span>
                </li>
              ))}
            </ul>
            <span className="mt-4 flex items-center rounded-xl border border-neutral/25 bg-primary px-3 py-2 text-sm font-medium text-accent w-full justify-center hover:bg-primary/70">
              {openLabel}
            </span>
          </div>
        </div>
      </button>

      {isOpen ? (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby={dialogId}
          aria-describedby={`${dialogId}-details`}
          className="fixed inset-0 z-50 flex items-center justify-center px-4 py-10"
        >
          <button
            type="button"
            aria-label={closeLabel}
            className="absolute inset-0 bg-primary/90 backdrop-blur-sm"
            onClick={() => setIsOpen(false)}
          />
          <div
            ref={dialogRef}
            tabIndex={-1}
            className="relative z-10 w-full max-w-5xl overflow-hidden rounded-3xl border border-neutral/20 bg-secondary shadow-2xl focus:outline-none"
          >
            <div className="flex items-center justify-between border-b border-neutral/20 px-6 py-4">
              <div className="flex items-center gap-3">
                <img
                  src={project.images.logo.src}
                  alt={project.images.logo.alt || `${project.title} logo`}
                  className="h-9 w-auto"
                  decoding="async"
                  width={200}
                  height={80}
                />
                <h3 id={dialogId} className="text-lg font-semibold text-accent">
                  {project.title}
                </h3>
              </div>
              <button
                ref={closeButtonRef}
                type="button"
                onClick={() => setIsOpen(false)}
                className="inline-flex items-center rounded-xl border border-neutral/25 bg-primary px-3 py-2 text-sm font-medium text-accent hover:bg-primary/70"
              >
                {closeLabel}
              </button>
            </div>

            <div className="grid gap-6 p-6 lg:grid-cols-2">
              <div className="overflow-hidden rounded-2xl border border-neutral/20">
                <img
                  src={project.images.large.src}
                  alt={label}
                  className="h-full w-full object-cover"
                  decoding="async"
                  width={1600}
                  height={1000}
                />
              </div>
              <div id={`${dialogId}-details`}>
                <p className="text-sm text-neutral">
                  <span className="font-medium text-accent">{project.role}</span>
                  {" · "}
                  <span>{project.stack}</span>
                  {project.year ? <span>{" · "}{project.year}</span> : null}
                </p>

                <ul className="mt-5 space-y-2 text-sm text-accent">
                  {project.highlights.map((highlight) => (
                    <li key={highlight} className="flex gap-2">
                      <span aria-hidden="true" className="mt-1 inline-block h-1.5 w-1.5 rounded-full bg-neutral" />
                      <span className="min-w-0">{highlight}</span>
                    </li>
                  ))}
                </ul>

                {project.note ? (
                  <p className="mt-5 text-sm text-neutral">{project.note}</p>
                ) : null}
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
};

export default Card;
